window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dbf2ae5f01c1e999"]={"versions": [{"id": "FIG-dbf2ae5f01c1e999", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion und Datenfluss-Synchronisation im AUTOSAR-V2X-Stack. Das Diagramm modelliert den asynchronen Ablauf zur Aktualisierung von Positions- und Zeitdaten zwischen einer Applikationskomponente (Vehicle Data Provider SW-C), dem V2X Management-Modul (<code>V2xM</code>) und dem GeoNetworking-Modul (<code>V2xGn</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lifelines):</p>\n<ul class=\"fig-list\">\n<li><code>Vehicle Data Provider SW-C</code>: Software-Komponente, die Fahrzeugzustandsdaten bereitstellt.</li>\n<li><code>«module» V2xM</code>: Basissoftware-Modul des V2X Management.</li>\n<li><code>«module» V2xGn</code>: Basissoftware-Modul für V2X GeoNetworking.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li>Synchroner Aufruf <code>V2xM_Vdp_SetPositionAndTime(positionAndTime: V2x_GnLocalPositionVectorType)</code> von <code>Vehicle Data Provider SW-C</code> an <code>V2xM</code>.</li>\n<li>Interner/lokaler Aufruf <code>Update ECU time (Gpt, StbM or other means)</code> an der Lifeline von <code>V2xM</code>.</li>\n<li>Synchroner Abruf <code>V2xM_GetPositionAndTime(Std_ReturnType, V2x_GnLocalPositionVectorType*)</code> von <code>V2xGn</code> an <code>V2xM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei voneinander entkoppelte Interaktionsschleifen (<code>loop</code>):</p>\n<ol class=\"fig-list\">\n<li><code>loop Application activation interval</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>Vehicle Data Provider SW-C</code> ruft synchron <code>V2xM_Vdp_SetPositionAndTime</code> mit dem Parameter <code>positionAndTime: V2x_GnLocalPositionVectorType</code> an <code>V2xM</code> auf.</li>\n<li>Während der Ausführung führt <code>V2xM</code> eine Selbstinteraktion zur Aktualisierung der Steuergerätezeit durch (<code>Update ECU time (Gpt, StbM or other means)</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>loop Every 100ms (V2xGn_MainFunction)</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Modul <code>V2xGn</code> ruft zyklisch im Raster seiner Hauptfunktion synchron <code>V2xM_GetPositionAndTime</code> auf, um die aktuellen Daten über einen Zeiger vom Typ <code>V2x_GnLocalPositionVectorType*</code> mit dem Rückgabetyp <code>Std_ReturnType</code> aus <code>V2xM</code> abzufragen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktualisierung und Bereitstellung der Positions- und Zeitvektoren erfolgt entkoppelt über <code>V2xM</code> als Vermittler. Entwickler müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Die Aktualisierungsrate der Anwendungsseite (<code>Application activation interval</code>) steuert das Setzen der Basisdaten in <code>V2xM</code>.</li>\n<li><code>V2xM</code> synchronisiert oder extrapoliert die Zeitbasis über hardwarenahe/zeitbezogene Module (<code>Gpt</code>, <code>StbM</code> o. ä.).</li>\n<li><code>V2xGn</code> tastet die aggregierten Daten mit fester 100-ms-Zyklizität über <code>V2xGn_MainFunction</code> gepuffert ab.</li>\n<li>Die Datentypen basieren auf <code>V2x_GnLocalPositionVectorType</code>.</li>\n</ul>"}, {"id": "FIG-5d9bc080a8496361", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion und Datenfluss-Synchronisation im AUTOSAR-V2X-Stack. Das Diagramm modelliert den asynchronen Ablauf zur Aktualisierung von Positions- und Zeitdaten zwischen einer Applikationskomponente (Vehicle Data Provider SW-C), dem V2X Management-Modul (<code>V2xM</code>) und dem GeoNetworking-Modul (<code>V2xGn</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lifelines):</p>\n<ul class=\"fig-list\">\n<li><code>Vehicle Data Provider SW-C</code>: Software-Komponente, die Fahrzeugzustandsdaten bereitstellt.</li>\n<li><code>«module» V2xM</code>: Basissoftware-Modul des V2X Management.</li>\n<li><code>«module» V2xGn</code>: Basissoftware-Modul für V2X GeoNetworking.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li>Synchroner Aufruf <code>V2xM_Vdp_SetPositionAndTime(positionAndTime: V2xM_PositionAndTimeType)</code> von <code>Vehicle Data Provider SW-C</code> an <code>V2xM</code>.</li>\n<li>Interner/lokaler Aufruf <code>Update ECU time (Gpt, StbM or other means)</code> an der Lifeline von <code>V2xM</code>.</li>\n<li>Synchroner Abruf <code>V2xM_GetPositionAndTime(Std_ReturnType, V2xM_PositionAndTimeType*)</code> von <code>V2xGn</code> an <code>V2xM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei voneinander entkoppelte Interaktionsschleifen (<code>loop</code>):</p>\n<ol class=\"fig-list\">\n<li><code>loop Application activation interval</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>Vehicle Data Provider SW-C</code> ruft synchron <code>V2xM_Vdp_SetPositionAndTime</code> mit dem Parameter <code>positionAndTime: V2xM_PositionAndTimeType</code> an <code>V2xM</code> auf.</li>\n<li>Während der Ausführung führt <code>V2xM</code> eine Selbstinteraktion zur Aktualisierung der Steuergerätezeit durch (<code>Update ECU time (Gpt, StbM or other means)</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>loop Every 100ms (V2xGn_MainFunction)</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Modul <code>V2xGn</code> ruft zyklisch im Raster seiner Hauptfunktion synchron <code>V2xM_GetPositionAndTime</code> auf, um die aktuellen Daten über einen Zeiger vom Typ <code>V2xM_PositionAndTimeType*</code> mit dem Rückgabetyp <code>Std_ReturnType</code> aus <code>V2xM</code> abzufragen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktualisierung und Bereitstellung der Positions- und Zeitvektoren erfolgt entkoppelt über <code>V2xM</code> als Vermittler. Entwickler müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Die Aktualisierungsrate der Anwendungsseite (<code>Application activation interval</code>) steuert das Setzen der Basisdaten in <code>V2xM</code>.</li>\n<li><code>V2xM</code> synchronisiert oder extrapoliert die Zeitbasis über hardwarenahe/zeitbezogene Module (<code>Gpt</code>, <code>StbM</code> o. ä.).</li>\n<li><code>V2xGn</code> tastet die aggregierten Daten mit fester 100-ms-Zyklizität über <code>V2xGn_MainFunction</code> gepuffert ab.</li>\n<li>Die Datentypen für Position und Zeit sind modulübergreifend als <code>V2xM_PositionAndTimeType</code> spezifiziert.</li>\n</ul>"}, {"id": "FIG-d63f90c9add2558a", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion und Datenfluss-Synchronisation im AUTOSAR-V2X-Stack. Das Diagramm modelliert den asynchronen Ablauf zur Aktualisierung von Positions- und Zeitdaten zwischen einer Applikationskomponente (Vehicle Data Provider SW-C), dem V2X Management-Modul (<code>V2xM</code>) und dem GeoNetworking-Modul (<code>V2xGn</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lifelines):</p>\n<ul class=\"fig-list\">\n<li><code>Vehicle Data Provider SW-C</code>: Software-Komponente, die Fahrzeugzustandsdaten bereitstellt.</li>\n<li><code>«module» V2xM</code>: Basissoftware-Modul des V2X Management.</li>\n<li><code>«module» V2xGn</code>: Basissoftware-Modul für V2X GeoNetworking.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li>Synchroner Aufruf <code>V2xM_Vdp_SetPositionAndTime(positionAndTime: V2xM_PositionAndTimeType)</code> von <code>Vehicle Data Provider SW-C</code> an <code>V2xM</code>.</li>\n<li>Interner/lokaler Aufruf <code>Update ECU time (Gpt, StbM or other means)</code> an der Lifeline von <code>V2xM</code>.</li>\n<li>Synchroner Abruf <code>V2xM_GetPositionAndTime(Std_ReturnType, V2xM_PositionAndTimeType*)</code> von <code>V2xGn</code> an <code>V2xM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei voneinander entkoppelte Interaktionsschleifen (<code>loop</code>):</p>\n<ol class=\"fig-list\">\n<li><code>loop Application activation interval</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>Vehicle Data Provider SW-C</code> ruft synchron <code>V2xM_Vdp_SetPositionAndTime</code> mit dem Parameter <code>positionAndTime: V2xM_PositionAndTimeType</code> an <code>V2xM</code> auf.</li>\n<li>Während der Ausführung führt <code>V2xM</code> eine Selbstinteraktion zur Aktualisierung der Steuergerätezeit durch (<code>Update ECU time (Gpt, StbM or other means)</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>loop Every 100ms (V2xGn_MainFunction)</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Modul <code>V2xGn</code> ruft zyklisch im Raster seiner Hauptfunktion synchron <code>V2xM_GetPositionAndTime</code> auf, um die aktuellen Daten über einen Zeiger vom Typ <code>V2xM_PositionAndTimeType*</code> mit dem Rückgabetyp <code>Std_ReturnType</code> aus <code>V2xM</code> abzufragen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktualisierung und Bereitstellung der Positions- und Zeitvektoren erfolgt entkoppelt über <code>V2xM</code> als Vermittler. Entwickler müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Die Aktualisierungsrate der Anwendungsseite (<code>Application activation interval</code>) steuert das Setzen der Basisdaten in <code>V2xM</code>.</li>\n<li><code>V2xM</code> synchronisiert oder extrapoliert die Zeitbasis über hardwarenahe/zeitbezogene Module (<code>Gpt</code>, <code>StbM</code> o. ä.).</li>\n<li><code>V2xGn</code> tastet die aggregierten Daten mit fester 100-ms-Zyklizität über <code>V2xGn_MainFunction</code> gepuffert ab.</li>\n<li>Die Datentypen für Position und Zeit sind modulübergreifend als <code>V2xM_PositionAndTimeType</code> spezifiziert.</li>\n</ul>"}], "trans": [{"from": "FIG-dbf2ae5f01c1e999", "to": "FIG-5d9bc080a8496361", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Parameter- und Rückgabedatentyp in den Funktionsaufrufen geändert:</li>\n<li><code>V2xM_Vdp_SetPositionAndTime(positionAndTime: ...)</code>: Parametertyp von <code>V2x_GnLocalPositionVectorType</code> zu <code>V2xM_PositionAndTimeType</code>.</li>\n<li><code>V2xM_GetPositionAndTime(Std_ReturnType, ...)</code>: Zeigertyp für Position und Zeit von <code>V2x_GnLocalPositionVectorType<em></code> zu <code>V2xM_PositionAndTimeType</em></code>.</li>\n</ul>"}, {"from": "FIG-5d9bc080a8496361", "to": "FIG-d63f90c9add2558a", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
